enum CoinControlViewType { manage, use }

/// PIVX send context: which kind of coins to pick (shield notes or
/// transparent outputs) and what they pay for, for the Core-style
/// summary (see [PivxWallet.coinControlSummary]).
typedef PivxCoinControlArgs = ({
  bool shieldNotes,
  Amount? sendAmount,
  bool toShield,
  bool subtractFee,
});

class CoinControlView extends ConsumerStatefulWidget {
  const CoinControlView({
    super.key,
    required this.walletId,
    required this.type,
    this.requestedTotal,
    this.selectedUTXOs,
    this.pivx,
  });

  static const routeName = "/coinControl";

  final String walletId;
  final CoinControlViewType type;
  final Amount? requestedTotal;
  final Set<UTXO>? selectedUTXOs;

  /// PIVX send context. When null on a shield-capable PIVX wallet the
  /// user switches between transparent outputs and shield notes.
  final PivxCoinControlArgs? pivx;

  @override
  ConsumerState<CoinControlView> createState() => _CoinControlViewState();
}

class _CoinControlViewState extends ConsumerState<CoinControlView> {
  final searchController = TextEditingController();
  final searchFocus = FocusNode();

  bool _isSearching = false;
  bool _showBlocked = false;

  CCSortDescriptor _sort = CCSortDescriptor.age;

  /// Sort direction; each sort starts on its natural one (largest
  /// amount, most confirmations, address A-Z).
  bool _ascending = false;

  Map<String, List<Id>>? _map;
  List<Id>? _list;

  final Set<UTXO> _selectedAvailable = {};
  final Set<UTXO> _selectedBlocked = {};

  /// PIVX wallets keep shield notes and transparent outputs apart; null
  /// for other wallets (no filter).
  bool? _shieldNotes;
  bool _canSwitchKind = false;

  Future<void> _refreshBalance() async {
    final coinControlInterface =
        ref.read(pWallets).getWallet(widget.walletId) as CoinControlInterface;
    await coinControlInterface.updateBalance();
  }

  bool _isConfirmed(UTXO utxo, int currentChainHeight, Wallet wallet) {
    return utxo.isConfirmed(
      currentChainHeight,
      wallet.cryptoCurrency.minConfirms,
      wallet.cryptoCurrency.minCoinbaseConfirms,
    );
  }

  /// Outputs on screen that may be selected right now.
  List<UTXO> _selectableShown(int currentHeight, Wallet wallet) {
    final ids = _list ?? _map?.values.expand((e) => e).toList() ?? const [];
    return MainDB.instance.isar.utxos
        .getAllSync(ids)
        .nonNulls
        .where(
          (u) =>
              widget.type == CoinControlViewType.manage ||
              (!u.isBlocked && _isConfirmed(u, currentHeight, wallet)),
        )
        .toList();
  }

  Widget _selectAllRow(int currentHeight) {
    final wallet = ref.read(pWallets).getWallet(widget.walletId);
    final shown = _selectableShown(currentHeight, wallet);
    final allSelected =
        shown.isNotEmpty &&
        shown.every(
          (u) => _selectedAvailable.contains(u) || _selectedBlocked.contains(u),
        );
    return Row(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        CustomTextButton(
          text: allSelected ? l10n.commonUnselectAll : l10n.commonSelectAll,
          enabled: shown.isNotEmpty,
          onTap: () {
            setState(() {
              for (final u in shown) {
                final set = u.isBlocked ? _selectedBlocked : _selectedAvailable;
                allSelected ? set.remove(u) : set.add(u);
              }
            });
          },
        ),
      ],
    );
  }

  /// PIVX Core-style figures for the current selection.
  Widget _pivxSummary(PivxWallet wallet, CryptoCurrency coin) {
    final args = widget.pivx;
    final s = wallet.coinControlSummary(
      selected: _selectedAvailable,
      toShield: args?.toShield ?? false,
      amount: args?.sendAmount,
      subtractFee: args?.subtractFee ?? false,
    );
    final fmt = ref.watch(pAmountFormatter(coin));
    final label = STextStyles.w500_12(context).copyWith(
      color: Theme.of(context).extension<StackColors>()!.textSubtitle1,
    );
    final value = STextStyles.w600_12(context);
    Widget cell(String name, String text, {String? copy}) => Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(name, style: label),
          Flexible(
            child: Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                Flexible(
                  child: Text(
                    text,
                    style: value,
                    textAlign: TextAlign.right,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
                if (copy != null) ...[
                  const SizedBox(width: 8),
                  IconCopyButton(data: copy),
                ],
              ],
            ),
          ),
        ],
      ),
    );
    final change = s.change;
    return Padding(
      padding: const EdgeInsets.fromLTRB(12, 6, 12, 6),
      child: Column(
        children: [
          Row(
            children: [
              Expanded(child: cell(l10n.coinControlQuantity, "${s.quantity}")),
              const SizedBox(width: 16),
              Expanded(child: cell(l10n.coinControlBytes, "~${s.bytes}")),
            ],
          ),
          cell(l10n.coinControlFee, "~${fmt.format(s.fee)}"),
          cell(
            l10n.coinControlAfterFee,
            fmt.format(s.afterFee),
            copy: s.afterFee.raw.isNegative
                ? null
                : fmt.format(
                    s.afterFee,
                    withUnitName: false,
                    indicatePrecisionLoss: false,
                  ),
          ),
          if (change != null)
            cell(
              l10n.txChange,
              change.raw.isNegative
                  ? l10n.coinControlInsufficient
                  : fmt.format(change),
            ),
        ],
      ),
    );
  }

  @override
  void initState() {
    final wallet = ref.read(pWallets).getWallet(widget.walletId);
    if (wallet is PivxWallet) {
      _shieldNotes = widget.pivx?.shieldNotes ?? false;
      _canSwitchKind = widget.pivx == null && wallet.supportsShield;
    }
    if (widget.selectedUTXOs != null) {
      _selectedAvailable.addAll(widget.selectedUTXOs!);
    }
    searchController.addListener(() {
      WidgetsBinding.instance.addPostFrameCallback((timeStamp) {
        setState(() {});
      });
    });
    super.initState();
  }

  @override
  void dispose() {
    searchController.dispose();
    searchFocus.dispose();
    super.dispose();
  }

