    final currentHeight = ref.watch(pWalletChainHeight(widget.walletId));

    final UtxoTagFilter? tagFilter = _shieldNotes == null
        ? null
        : (key: kPivxShieldNoteKey, present: _shieldNotes!);

    if (_sort == CCSortDescriptor.address && !_isSearching) {
      _list = null;
      _map = MainDB.instance.queryUTXOsGroupedByAddressSync(
        walletId: widget.walletId,
        filter: CCFilter.all,
        sort: _sort,
        searchTerm: "",
        cryptoCurrency: coin,
        tagFilter: tagFilter,
        ascending: _ascending,
      );
    } else {
      _map = null;
      _list = MainDB.instance.queryUTXOsSync(
        walletId: widget.walletId,
        filter: _isSearching
            ? CCFilter.all
            : _showBlocked
            ? CCFilter.frozen
            : CCFilter.available,
        sort: _sort,
        searchTerm: _isSearching ? searchController.text : "",
        cryptoCurrency: coin,
        tagFilter: tagFilter,
        ascending: _ascending,
      );
    }

    return WillPopScope(
      onWillPop: () async {
        unawaited(_refreshBalance());
        Navigator.of(context).pop(
          widget.type == CoinControlViewType.use ? _selectedAvailable : null,
