                                                  );
                                              if (mounted &&
                                                  result == "refresh") {
                                                setState(() {});
                                              }
                                            },
                                          );
                                        }).toList(),
                                      );
                                    },
                                  ),
                                ),
                      ],
                    ),
                  ),
                ),
                if (((_showBlocked && _selectedBlocked.isNotEmpty) ||
                        (!_showBlocked && _selectedAvailable.isNotEmpty)) &&
                    widget.type == CoinControlViewType.manage)
                  Container(
                    decoration: BoxDecoration(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .backgroundAppBar,
                      boxShadow: [
                        Theme.of(context)
                            .extension<StackColors>()!
                            .standardBoxShadow,
                      ],
                    ),
                    child: Padding(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Builder(
                            builder: (context) {
                              final sel = _showBlocked
                                  ? _selectedBlocked
                                  : _selectedAvailable;
                              final sum = sel
                                  .fold<int>(0, (p, u) => p + u.value)
                                  .toAmountAsRaw(
                                    fractionDigits: coin.fractionDigits,
                                  );
                              return Text(
                                "${l10n.coinControlSelected(sel.length)} · "
                                "${ref.watch(pAmountFormatter(coin)).format(sum)}",
                                style: STextStyles.w600_14(context),
                              );
                            },
                          ),
                          const SizedBox(height: 12),
                          SecondaryButton(
                            label: _showBlocked
                                ? l10n.coinControlUnfreeze
                                : l10n.coinControlFreeze,
                            onPressed: () async {
                              if (_showBlocked) {
                                await MainDB.instance.putUTXOs(
                                  _selectedBlocked
                                      .map((e) => e.copyWith(isBlocked: false))
                                      .toList(),
                                );
                                _selectedBlocked.clear();
                              } else {
                                await MainDB.instance.putUTXOs(
                                  _selectedAvailable
                                      .map((e) => e.copyWith(isBlocked: true))
                                      .toList(),
                                );
                                _selectedAvailable.clear();
                              }
                              setState(() {});
                            },
                          ),
                        ],
                      ),
                    ),
                  ),
                if (!_showBlocked && widget.type == CoinControlViewType.use)
                  Container(
                    decoration: BoxDecoration(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .backgroundAppBar,
                      boxShadow: [
                        Theme.of(context)
                            .extension<StackColors>()!
                            .standardBoxShadow,
                      ],
                    ),
                    child: Padding(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        children: [
                          RoundedWhiteContainer(
                            padding: const EdgeInsets.all(0),
                            child: Column(
                              children: [
                                Padding(
                                  padding: const EdgeInsets.all(12),
                                  child: Row(
                                    mainAxisAlignment:
                                        MainAxisAlignment.spaceBetween,
                                    children: [
                                      Text(
                                        l10n.coinControlSelectedAmount,
                                        style: STextStyles.w600_14(context),
                                      ),
                                      Builder(
                                        builder: (context) {
                                          final int selectedSumInt =
                                              _selectedAvailable.isEmpty
                                              ? 0
                                              : _selectedAvailable
                                                    .map((e) => e.value)
                                                    .reduce(
                                                      (value, element) =>
                                                          value += element,
                                                    );
                                          final selectedSum = selectedSumInt
                                              .toAmountAsRaw(
                                                fractionDigits:
                                                    coin.fractionDigits,
                                              );
                                          return Row(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              SelectableText(
                                                ref
                                                    .watch(
                                                      pAmountFormatter(coin),
                                                    )
                                                    .format(selectedSum),
                                                style:
                                                    widget.requestedTotal ==
                                                        null
                                                    ? STextStyles.w600_14(
                                                        context,
                                                      )
                                                    : STextStyles.w600_14(
                                                        context,
                                                      ).copyWith(
                                                        color:
                                                            selectedSum >=
                                                                widget
                                                                    .requestedTotal!
                                                            ? Theme.of(context)
                                                                  .extension<
                                                                    StackColors
                                                                  >()!
                                                                  .accentColorGreen
                                                            : Theme.of(context)
                                                                  .extension<
                                                                    StackColors
                                                                  >()!
                                                                  .accentColorRed,
                                                      ),
                                              ),
                                              const SizedBox(width: 8),
                                              IconCopyButton(
                                                data: ref
                                                    .watch(
                                                      pAmountFormatter(coin),
                                                    )
                                                    .format(
                                                      selectedSum,
                                                      withUnitName: false,
                                                      indicatePrecisionLoss:
                                                          false,
                                                    ),
                                              ),
                                            ],
                                          );
                                        },
                                      ),
                                    ],
                                  ),
                                ),
                                if (widget.requestedTotal != null)
                                  Container(
                                    width: double.infinity,
                                    height: 1.5,
                                    color: Theme.of(context)
                                        .extension<StackColors>()!
                                        .backgroundAppBar,
                                  ),
                                if (widget.requestedTotal != null)
                                  Padding(
                                    padding: const EdgeInsets.all(12),
                                    child: Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.spaceBetween,
                                      children: [
                                        Text(
                                          l10n.coinControlAmountToSend,
                                          style: STextStyles.w600_14(context),
                                        ),
                                        SelectableText(
                                          ref
                                              .watch(pAmountFormatter(coin))
                                              .format(widget.requestedTotal!),
                                          style: STextStyles.w600_14(context),
                                        ),
                                      ],
                                    ),
                                  ),
                                if (_selectedAvailable.isNotEmpty &&
                                    ref
                                            .watch(pWallets)
                                            .getWallet(widget.walletId)
                                        is PivxWallet) ...[
                                  Container(
                                    width: double.infinity,
                                    height: 1.5,
                                    color: Theme.of(context)
                                        .extension<StackColors>()!
                                        .backgroundAppBar,
                                  ),
                                  _pivxSummary(
                                    ref
                                            .watch(pWallets)
                                            .getWallet(widget.walletId)
                                        as PivxWallet,
                                    coin,
                                  ),
                                ],
                              ],
                            ),
                          ),
                          const SizedBox(height: 12),
                          PrimaryButton(
                            label: l10n.coinControlUseCoins,
                            enabled: _selectedAvailable.isNotEmpty,
                            onPressed: () async {
                              if (searchFocus.hasFocus) {
                                searchFocus.unfocus();
                              }
                              Navigator.of(context).pop(_selectedAvailable);
                            },
                          ),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
